rez.sheets_vykdyti:
public static function vykdyti( $redirect, $veiksmas, $ids ) {
	if ( self::VEIKSMAS !== $veiksmas ) { return $redirect; }
	$ids = array_map( 'intval', (array) $ids );
	if ( ! $ids ) { return $redirect; }
	set_transient( 'ps_sheets_' . get_current_user_id(), $ids, 900 );
	return add_query_arg( [ 'page' => 'ps-lapai', 'ps_ready' => 1 ], admin_url( 'admin.php' ) );
}

rez.sheets_veiksmas:
public static function veiksmas( $veiksmai ) {
	$veiksmai[ self::VEIKSMAS ] = 'Petshop: surinkimo ir pakavimo lapai';
	return $veiksmai;
}

rez.sheets_uzs_veiksmas:
public static function uzsakymo_veiksmas( $veiksmai ) {
	$veiksmai['ps_lapas'] = 'Petshop: pakavimo lapas';
	return $veiksmai;
}

rez.sheets_vieno:
public static function vieno_uzsakymo( $order ) {
	$id = is_object( $order ) ? $order->get_id() : (int) $order;
	set_transient( 'ps_sheets_' . get_current_user_id(), [ $id ], 900 );
}

